<svelte:options css="injected" />
<script lang="ts">
 import Theme from '../../shared/Theme.svelte';import Icon from '../date-picker/DatePickerIcon.svelte';
 let {page,total,pageSize=20,onchange,disabled=false}:{page:number;total:number;pageSize?:number;onchange?:(page:number)=>void;disabled?:boolean}=$props();const count=$derived(Math.max(1,Math.ceil(total/Math.max(1,pageSize))));const pages=$derived(Array.from({length:Math.min(7,count)},(_,i)=>Math.max(1,Math.min(page-3,count-6))+i));
</script>
<Theme><nav class="mc-ui-pager" aria-label="分页"><span>共 {total} 条</span><button class="mc-ui-pager__btn-prev" aria-label="上一页" disabled={disabled||page<=1} onclick={()=>onchange?.(page-1)}><Icon name="left"/></button><ul class="mc-ui-pager__pages">{#each pages as item}<li class:is-active={item===page}><button aria-current={item===page?'page':undefined} aria-label="第 {item} 页" {disabled} onclick={()=>onchange?.(item)}>{item}</button></li>{/each}</ul><button class="mc-ui-pager__btn-next" aria-label="下一页" disabled={disabled||page>=count} onclick={()=>onchange?.(page+1)}><Icon name="right"/></button></nav></Theme>
<style>nav{display:flex;align-items:center;flex-wrap:wrap}ul{list-style:none;margin:0;padding:0}li button{border:0;border-radius:inherit;background:transparent;width:100%;height:100%;font:inherit;color:inherit;cursor:pointer;padding:0}li button:disabled{color:#c2c2c2;cursor:not-allowed}</style>
